"use client";
import { useEffect, useState } from "react"; import { Moon, Sun } from "lucide-react";
export function ThemeToggle(){const [dark,setDark]=useState(true);useEffect(()=>{setDark(!document.documentElement.classList.contains("light"))},[]);function toggle(){const next=!dark;const change=()=>{document.documentElement.classList.toggle("light",!next);localStorage.setItem("theme",next?"dark":"light");setDark(next)};const doc=document as Document & {startViewTransition?:(callback:()=>void)=>void};if(doc.startViewTransition)doc.startViewTransition(change);else{document.documentElement.classList.add("theme-fallback");change();setTimeout(()=>document.documentElement.classList.remove("theme-fallback"),650)}}return <button className="theme-toggle" onClick={toggle} aria-label={dark?"Switch to light theme":"Switch to dark theme"}>{dark?<Sun size={16}/>:<Moon size={16}/>}</button>}
